import java.util.Scanner;

public class Machine {
    private static String status = "Created";
    private static boolean approved = false;
    private static boolean cancelled = false;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("READY");
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.equals("SNAPSHOT")) {
                printState();
            } else if (line.startsWith("FIRE ")) {
                String event = line.substring(5).trim();
                if (fire(event)) {
                    System.out.println("APPLIED");
                    printState();
                } else {
                    System.out.println("REJECTED");
                }
            }
        }
    }

    private static void printState() {
        System.out.println("STATE status=\"" + status + "\";approved=" + approved + ";cancelled=" + cancelled);
    }

    private static boolean fire(String event) {
        switch (event) {
            case "Approve":
                if (status.equals("Created")) {
                    status = "Approved";
                    approved = true;
                    return true;
                }
                return false;
            case "Cancel":
                if (status.equals("Created") || status.equals("Approved")) {
                    status = "Cancelled";
                    cancelled = true;
                    approved = false;
                    return true;
                }
                return false;
            case "Execute":
                if (approved) {
                    status = "Executed";
                    return true;
                }
                return false;
            default:
                return false;
        }
    }
}

import java.util.Scanner;

public class Machine {

    enum Status { Ready, Done }

    static Status status = Status.Ready;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("READY");
        System.out.flush();
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.equals("SNAPSHOT")) {
                printState();
            } else if (line.startsWith("FIRE ")) {
                String event = line.substring(5).trim();
                fire(event);
            }
            System.out.flush();
        }
    }

    static void printState() {
        System.out.println("STATE status=\"" + status.name() + "\"");
    }

    static void fire(String event) {
        if (event.equals("Stay") && status == Status.Ready) {
            status = Status.Ready;
            System.out.println("APPLIED");
            printState();
        } else if (event.equals("Finish") && status == Status.Ready) {
            status = Status.Done;
            System.out.println("APPLIED");
            printState();
        } else {
            System.out.println("REJECTED");
        }
    }
}

import java.util.Scanner;

public class Machine {
    static int x = 0;
    static int y = 1;
    static boolean flag = false;

    static void printState() {
        System.out.println("STATE x=" + x + ";y=" + y + ";flag=" + flag);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("READY");
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.equals("SNAPSHOT")) {
                printState();
            } else if (line.startsWith("FIRE ")) {
                String event = line.substring(5).trim();
                if (event.equals("Swap")) {
                    if (x == 0 && !flag) {
                        int newX = y;
                        int newY = x;
                        x = newX;
                        y = newY;
                        System.out.println("APPLIED");
                        printState();
                    } else {
                        System.out.println("REJECTED");
                    }
                } else if (event.equals("Reset")) {
                    if (x == 1) {
                        x = 0;
                        y = 1;
                        System.out.println("APPLIED");
                        printState();
                    } else {
                        System.out.println("REJECTED");
                    }
                } else {
                    System.out.println("REJECTED");
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Machine {
  static String status = "Created";
  static boolean approved = false;
  static boolean cancelled = false;

  static void state() {
    System.out.println("STATE status=" + status + ";approved=" + approved + ";cancelled=" + cancelled);
  }

  public static void main(String[] args) throws Exception {
    System.out.println("READY");
    BufferedReader input = new BufferedReader(new InputStreamReader(System.in));
    String line;
    while ((line = input.readLine()) != null) {
      if (line.equals("SNAPSHOT")) {
        state();
      } else if (line.startsWith("FIRE ")) {
        String event = line.substring(5);
        if (event.equals("Approve") && status.equals("Created")) {
          status = "Approved";
          approved = true;
          System.out.println("APPLIED");
          state();
        } else if (event.equals("Cancel") && (status.equals("Created") || status.equals("Approved"))) {
          status = "Cancelled";
          cancelled = true;
          approved = false;
          System.out.println("APPLIED");
          state();
        } else if (event.equals("Execute")) {
          status = "Executed";
          System.out.println("APPLIED");
          state();
        } else {
          System.out.println("REJECTED");
        }
      }
      System.out.flush();
    }
  }
}

